{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "For all four datasets, blend the baseline BCE loss equally with pairwise softplus loss on the existing sampled pairs and valid-position mask. This may improve candidate ordering while retaining calibration, without changing architecture, inference, sampling, optimizer, or training schedule.",
      "edits": [
        {
          "find": "            loss = bce_criterion(pos_logits[indices], pos_labels)\n            loss = loss + bce_criterion(neg_logits[indices], neg_labels)",
          "replace": "            baseline_loss = bce_criterion(pos_logits[indices], pos_labels)\n            baseline_loss = baseline_loss + bce_criterion(neg_logits[indices], neg_labels)\n            pairwise_loss = torch.nn.functional.softplus(\n                neg_logits[indices] - pos_logits[indices]\n            ).mean()\n            loss = 0.5 * baseline_loss + 0.5 * pairwise_loss"
        }
      ]
    }
  ],
  "change_summary": "Blend baseline BCE and pairwise ranking loss with equal weights across all four category models. Checkpoint formats and predictor behavior remain compatible."
}
